import React, { useEffect, useState } from 'react';
import api from '../services/api';

const tabs = [['overview','📊 Vue d\'ensemble'],['profs','👨‍🏫 Professeurs'],['users','👥 Utilisateurs'],['reservations','📅 Réservations'],['referentiel','📚 Référentiel']];

export default function Admin() {
  const [tab, setTab] = useState('overview');
  const [stats, setStats] = useState({});
  const [profs, setProfs] = useState([]);
  const [pending, setPending] = useState([]);

  useEffect(() => {
    api.get('/api/admin/stats').then(r => setStats(r.data)).catch(() => {});
    api.get('/api/professeurs/').then(r => setProfs(r.data)).catch(() => {});
    api.get('/api/admin/professeurs/pending').then(r => setPending(r.data)).catch(() => {});
  }, []);

  async function valider(id) {
    await api.put(`/api/admin/professeurs/${id}/valider`);
    setPending(p => p.filter(x => x.id !== id));
    alert('✅ Professeur validé');
  }
  async function refuser(id) {
    await api.put(`/api/admin/professeurs/${id}/refuser`);
    setPending(p => p.filter(x => x.id !== id));
  }

  const statCards = [
    { icon:'👥', val: stats.total_users || 0, lbl:'Utilisateurs totaux', color:'#6c63ff', bg:'rgba(108,99,255,.1)' },
    { icon:'👨‍🏫', val: stats.total_professeurs || 0, lbl:'Professeurs validés', color:'#43e97b', bg:'rgba(67,233,123,.1)' },
    { icon:'⚠️', val: stats.en_attente || 0, lbl:'En attente validation', color:'#f59e0b', bg:'rgba(245,158,11,.1)' },
    { icon:'📅', val: stats.total_reservations || 0, lbl:'Réservations totales', color:'#38bdf8', bg:'rgba(56,189,248,.1)' },
  ];

  const tabStyle = t => ({ flex: 1, padding: '8px 4px', textAlign: 'center', borderRadius: 8, cursor: 'pointer', fontWeight: 600, fontSize: '.78rem', transition: '.2s', background: tab === t ? '#6c63ff' : 'transparent', color: tab === t ? '#fff' : 'var(--text2)' });

  return (
    <div style={{ padding: 32 }}>
      <div style={{ fontFamily: 'Syne', fontSize: '1.2rem', fontWeight: 700, marginBottom: 24 }}>🛠 Dashboard Administrateur</div>

      {/* Stats */}
      <div style={{ display: 'grid', gridTemplateColumns: 'repeat(4,1fr)', gap: 20, marginBottom: 24 }}>
        {statCards.map(s => (
          <div key={s.lbl} style={{ background: 'var(--card)', border: '1px solid var(--border)', borderRadius: 16, padding: 20, display: 'flex', alignItems: 'center', gap: 16 }}>
            <div style={{ width: 48, height: 48, borderRadius: 12, background: s.bg, display: 'flex', alignItems: 'center', justifyContent: 'center', fontSize: '1.4rem' }}>{s.icon}</div>
            <div>
              <div style={{ fontFamily: 'Syne', fontSize: '1.7rem', fontWeight: 800, color: s.color }}>{s.val}</div>
              <div style={{ fontSize: '.8rem', color: 'var(--text2)' }}>{s.lbl}</div>
            </div>
          </div>
        ))}
      </div>

      {/* Tabs */}
      <div style={{ display: 'flex', background: 'var(--surface2)', borderRadius: 12, padding: 4, marginBottom: 24, gap: 2 }}>
        {tabs.map(([k, l]) => <div key={k} style={tabStyle(k)} onClick={() => setTab(k)}>{l}</div>)}
      </div>

      {/* Pending validation alert */}
      {pending.length > 0 && tab !== 'profs' && (
        <div style={{ background: 'rgba(245,158,11,.05)', border: '1px solid rgba(245,158,11,.3)', borderRadius: 12, padding: 16, marginBottom: 20, display: 'flex', alignItems: 'center', gap: 10 }}>
          ⚠️ <span style={{ fontWeight: 600 }}>{pending.length} professeur(s) en attente de validation</span>
          <button onClick={() => setTab('profs')} style={{ marginLeft: 'auto', padding: '6px 14px', background: '#f59e0b', color: '#000', border: 'none', borderRadius: 8, fontWeight: 600, cursor: 'pointer', fontSize: '.82rem' }}>Vérifier →</button>
        </div>
      )}

      {tab === 'overview' && (
        <div style={{ display: 'grid', gridTemplateColumns: '1fr 1fr', gap: 20 }}>
          <div style={{ background: 'var(--card)', border: '1px solid var(--border)', borderRadius: 16, padding: 24 }}>
            <div style={{ fontWeight: 600, marginBottom: 16 }}>📚 Matières les plus demandées</div>
            {[['Mathématiques',85,'#6c63ff'],['Informatique',72,'#38bdf8'],['Physique',60,'#43e97b'],['Français',48,'#f59e0b'],['Anglais',35,'#ff6584']].map(([m,p,c]) => (
              <div key={m} style={{ display: 'flex', alignItems: 'center', gap: 12, marginBottom: 10 }}>
                <span style={{ width: 120, fontSize: '.8rem', color: 'var(--text2)', textAlign: 'right' }}>{m}</span>
                <div style={{ flex: 1, height: 10, background: 'var(--surface2)', borderRadius: 5, overflow: 'hidden' }}>
                  <div style={{ height: '100%', background: c, borderRadius: 5, width: `${p}%` }} />
                </div>
                <span style={{ width: 40, fontSize: '.8rem', fontWeight: 600, color: c }}>{p}%</span>
              </div>
            ))}
          </div>
          <div style={{ background: 'var(--card)', border: '1px solid var(--border)', borderRadius: 16, padding: 24 }}>
            <div style={{ fontWeight: 600, marginBottom: 16 }}>🏆 Top Professeurs</div>
            {profs.slice(0, 5).map((p, i) => (
              <div key={p.id} style={{ display: 'flex', alignItems: 'center', gap: 12, padding: '10px 0', borderBottom: '1px solid var(--border)' }}>
                <div style={{ width: 28, height: 28, borderRadius: '50%', background: ['linear-gradient(135deg,#f59e0b,#ef4444)','linear-gradient(135deg,#6c63ff,#8b5cf6)','linear-gradient(135deg,#43e97b,#38bdf8)','var(--surface2)','var(--surface2)'][i], display: 'flex', alignItems: 'center', justifyContent: 'center', fontSize: '.8rem', fontWeight: 700 }}>{i + 1}</div>
                <div style={{ flex: 1 }}>
                  <div style={{ fontSize: '.85rem', fontWeight: 600 }}>{p.user_nom}</div>
                  <div style={{ fontSize: '.75rem', color: 'var(--text2)' }}>{p.matieres?.[0]} · {p.ville}</div>
                </div>
                <span style={{ color: '#f59e0b' }}>★ {parseFloat(p.note_moyenne || 0).toFixed(1)}</span>
              </div>
            ))}
          </div>
        </div>
      )}

      {tab === 'profs' && (
        <div>
          {pending.length > 0 && (
            <div style={{ background: 'var(--card)', border: '1px solid rgba(245,158,11,.3)', borderRadius: 16, padding: 20, marginBottom: 20 }}>
              <div style={{ fontWeight: 600, marginBottom: 12 }}>⚠️ Professeurs en attente de validation</div>
              {pending.map(p => (
                <div key={p.id} style={{ display: 'flex', alignItems: 'center', justifyContent: 'space-between', padding: 12, background: 'var(--surface2)', borderRadius: 10, marginBottom: 8 }}>
                  <div>
                    <div style={{ fontWeight: 600, fontSize: '.88rem' }}>{p.nom}</div>
                    <div style={{ fontSize: '.78rem', color: 'var(--text2)' }}>{p.email}</div>
                  </div>
                  <div style={{ display: 'flex', gap: 8 }}>
                    <button onClick={() => valider(p.id)} style={{ padding: '6px 12px', background: 'rgba(67,233,123,.15)', color: '#43e97b', border: '1px solid rgba(67,233,123,.3)', borderRadius: 8, cursor: 'pointer', fontWeight: 600, fontSize: '.8rem' }}>✅ Valider</button>
                    <button onClick={() => refuser(p.id)} style={{ padding: '6px 12px', background: 'rgba(255,101,132,.15)', color: '#ff6584', border: '1px solid rgba(255,101,132,.3)', borderRadius: 8, cursor: 'pointer', fontWeight: 600, fontSize: '.8rem' }}>❌ Refuser</button>
                  </div>
                </div>
              ))}
            </div>
          )}
          <div style={{ background: 'var(--card)', border: '1px solid var(--border)', borderRadius: 16, overflow: 'hidden' }}>
            <div style={{ overflowX: 'auto' }}>
              <table style={{ width: '100%', borderCollapse: 'collapse' }}>
                <thead>
                  <tr>{['Professeur','Matière','Ville','Note','Statut','Actions'].map(h => <th key={h} style={{ background: 'var(--surface2)', color: 'var(--text2)', fontSize: '.72rem', textTransform: 'uppercase', padding: '12px 16px', textAlign: 'left', borderBottom: '1px solid var(--border)' }}>{h}</th>)}</tr>
                </thead>
                <tbody>
                  {profs.map(p => (
                    <tr key={p.id}>
                      <td style={{ padding: '14px 16px', fontWeight: 600, fontSize: '.85rem' }}>{p.user_nom}</td>
                      <td style={{ padding: '14px 16px' }}><span style={{ background: 'rgba(108,99,255,.15)', color: '#6c63ff', fontSize: '.72rem', fontWeight: 600, padding: '2px 8px', borderRadius: 20 }}>{p.matieres?.[0]}</span></td>
                      <td style={{ padding: '14px 16px', color: 'var(--text2)', fontSize: '.85rem' }}>{p.ville}</td>
                      <td style={{ padding: '14px 16px', color: '#f59e0b' }}>★ {parseFloat(p.note_moyenne || 0).toFixed(1)}</td>
                      <td style={{ padding: '14px 16px' }}><span style={{ background: p.statut_validation === 'validé' ? 'rgba(67,233,123,.15)' : 'rgba(245,158,11,.15)', color: p.statut_validation === 'validé' ? '#43e97b' : '#f59e0b', fontSize: '.72rem', fontWeight: 600, padding: '2px 8px', borderRadius: 20 }}>{p.statut_validation}</span></td>
                      <td style={{ padding: '14px 16px' }}><button style={{ padding: '5px 10px', background: 'rgba(255,101,132,.15)', color: '#ff6584', border: '1px solid rgba(255,101,132,.3)', borderRadius: 6, cursor: 'pointer', fontSize: '.75rem' }}>🗑</button></td>
                    </tr>
                  ))}
                </tbody>
              </table>
            </div>
          </div>
        </div>
      )}

      {tab === 'referentiel' && (
        <div style={{ display: 'grid', gridTemplateColumns: 'repeat(3,1fr)', gap: 20 }}>
          {[['📚 Matières',['Mathématiques','Physique','Chimie','Français','Anglais','Arabe','SVT','Histoire-Géo','Informatique','Philosophie']],
            ['🎓 Niveaux',['Primaire','Collège','Lycée 1ère','Lycée 2ème','Lycée 3ème (Bac)','Université L1','Master']],
            ['📍 Villes',['Tunis','Sfax','Sousse','Monastir','Nabeul','Bizerte','Kairouan','Ariana']]
          ].map(([title, items]) => (
            <div key={title} style={{ background: 'var(--card)', border: '1px solid var(--border)', borderRadius: 16, padding: 20 }}>
              <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: 12 }}>
                <div style={{ fontWeight: 600 }}>{title}</div>
                <button style={{ padding: '5px 10px', background: 'linear-gradient(135deg,#6c63ff,#8b5cf6)', color: '#fff', border: 'none', borderRadius: 8, cursor: 'pointer', fontSize: '.78rem', fontWeight: 600 }}>+ Ajouter</button>
              </div>
              {items.map(item => (
                <div key={item} style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', padding: '7px 0', borderBottom: '1px solid var(--border)' }}>
                  <span style={{ fontSize: '.83rem' }}>{item}</span>
                  <div style={{ display: 'flex', gap: 4 }}>
                    <button style={{ padding: '3px 8px', background: 'var(--surface2)', border: '1px solid var(--border)', borderRadius: 6, cursor: 'pointer', fontSize: '.75rem' }}>✏️</button>
                    <button style={{ padding: '3px 8px', background: 'rgba(255,101,132,.1)', border: '1px solid rgba(255,101,132,.2)', borderRadius: 6, cursor: 'pointer', fontSize: '.75rem', color: '#ff6584' }}>🗑</button>
                  </div>
                </div>
              ))}
            </div>
          ))}
        </div>
      )}
    </div>
  );
}
